(function(){
'use strict';
const $=s=>document.querySelector(s),extraKey='cheongnyeonpick-next-ui-v5';
let extra={saved:[],files:[],goal:'',submitted:false,receipt:''};
try{const v=JSON.parse(localStorage.getItem(extraKey)||'null');if(v){extra.saved=Array.isArray(v.saved)?v.saved.filter(n=>[1,2,3].includes(n)):[];extra.files=Array.isArray(v.files)?v.files.filter(d=>d&&typeof d.id==='string'&&typeof d.name==='string').map(d=>({id:d.id.slice(0,80),name:d.name.slice(0,160),type:String(d.type||'').slice(0,80),size:Number(d.size)||0,date:String(d.date||''),policy:[1,2,3].includes(d.policy)?d.policy:1,archived:!!d.archived})):[];extra.goal=typeof v.goal==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v.goal)?v.goal:'';extra.submitted=v.submitted===true;extra.receipt=String(v.receipt||'').slice(0,100);}}catch(_){}
let extraStored=true;
function saveExtra(){try{localStorage.setItem(extraKey,JSON.stringify(extra));return true;}catch(_){extraStored=false;return false;}}
function savedFeedback(text){toast(extraStored?text:'현재 화면에 반영했어요. 브라우저 저장이 안 돼 다시 열면 유지되지 않을 수 있어요.');}
const simpleIcon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${({bookmark:'<path d="M6 3h12v18l-6-4-6 4Z"/>',plus:'<path d="M12 4v16M4 12h16"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>'})[name]||''}</svg>`;
const dateISO=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const displayDate=v=>v?v.replaceAll('-','.'):'미설정';
const pad=v=>String(v).padStart(2,'0');
const profileStatuses=['대학 재학','휴학','졸업','구직 중','재직 중','창업'];
let compare=[],purpose='',regionFilter='전체',studentFilter='전체',recruitFilter='전체',savedFilter=false,filtersExpanded=false,prepMode='list',calendarOffset=0,showArchived=false;
let future={residence:'천안시',school:'천안시',status:'졸업',employment:'구직 중'},scenarioSnapshot=null,onlyChanged=false;
walletUI.history=walletUI.history.filter(h=>Number.isFinite(Date.parse(h.time)));
const liveFiles=()=>extra.files.filter(d=>!d.archived);
function crumb(name){return `<div class="board-kicker"><span>나의 다음 &nbsp;/&nbsp; <strong>${name}</strong></span><span>YOUR NEXT, ONE PICK AT A TIME.</span></div>`;}
function selectOptions(arr,value){return [...new Set([...arr,value])].map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v||'해당 없음')}</option>`).join('');}
const coreDialog=openDialog;
openDialog=function(title,body){const d=$('#infoDialog');d.classList.remove('compare-dialog');$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=body;if(!d.open)d.showModal();};
const corePass=profilePanel;
profilePanel=function(){const box=document.createElement('div');box.innerHTML=corePass();box.querySelector('.pass-header strong').textContent='MY LIVING PASS';box.querySelector('.pass-body').insertAdjacentHTML('beforeend','<p class="pass-direct">추천에 사용하는 정보 · 직접 입력</p>');box.querySelector('.policy-pass').insertAdjacentHTML('beforeend','<span class="pass-stamp" aria-hidden="true">MY NEXT<br>STARTS<br>HERE ↗</span>');return box.innerHTML;};
const oldHome=home;
card=function(p){const saved=extra.saved.includes(p.id);const catIcon={주거:'home',일자리:'user',교육:'school'}[p.cat]||'file';return `<article class="policy-card" data-category="${p.cat}"><div class="ticket-band"><span class="ticket-category">${icon(catIcon)}${p.cat}<span class="ticket-number">/ PICK 0${p.id}</span></span><button class="card-star ${saved?'is-saved':''}" data-policy-save="${p.id}" aria-label="${esc(p.title)} ${saved?'저장 취소':'저장'}" aria-pressed="${saved}">${simpleIcon('bookmark')}</button></div><div class="ticket-content"><p class="detail-meta-note">${p.org} · 시연 예시</p><h3><button class="policy-title-button" data-policy="${p.id}">${p.title}</button></h3><p class="policy-description">${p.desc}</p><div class="policy-meta" style="margin-top:14px"><span class="badge ${p.state}">${p.stateText}</span><span class="detail-meta-note">모집 상태 확인 필요</span></div><p class="policy-hint">${icon('info')}<span>${p.reason}</span></p></div><div class="policy-foot"><label class="card-compare"><input type="checkbox" data-policy-compare="${p.id}" ${compare.includes(p.id)?'checked':''} aria-label="${esc(p.title)} 비교 선택">비교 담기</label><button class="text-button" data-policy="${p.id}">내 조건 확인 ${icon('arrow')}</button></div></article>`;};
home=function(){const box=document.createElement('div');box.innerHTML=oldHome();const hero=box.querySelector('.board-hero'),overview=box.querySelector('.overview');hero.querySelector('.hero-sticker').textContent='나에게 맞는 가능성 ↗';hero.querySelector('.highlight-word').textContent='가볍게 픽.';hero.querySelector('.hero-copy>p').innerHTML='사는 곳과 학교, 지금의 나를 함께 살펴보고<br>정책 발견부터 신청 준비까지 한 칸씩 이어가요.';const done=state.completed.size;return crumb('나의 보드')+hero.outerHTML+overview.outerHTML+`<div class="next-today"><section class="today-note"><div class="today-note-head"><h2>오늘의 다음 한 칸</h2><span class="badge neutral">${5-done}개 남음</span></div><div class="today-row"><span class="today-index">01</span><div><strong>주거 지원, 내 생활권도 인정될까?</strong><p>주민등록지와 학교 소재지 기준을 확인해요.</p></div><button class="text-button" data-policy="1">조건 확인${icon('arrow')}</button></div><div class="today-row"><span class="today-index">02</span><div><strong>${done===5?'준비 완료! 제출 여부를 확인해요.':'서류 준비, 이어서 한 칸'}</strong><p>${esc(getPolicy(state.preparedPolicy).title)} · ${done}/5 점검</p></div><button class="text-button" data-route="apply">이어가기${icon('arrow')}</button></div></section><section class="pocket-peek"><span class="mono-kicker">MY POCKET</span><h3>내 문서가 모이면,<br>다음 준비는 더 가볍게.</h3><p>필요한 서류와 연결된 정책을 전자지갑에서 함께 확인해요.</p><span class="pocket-doodle" aria-hidden="true"></span><button class="text-button" data-route="wallet">전자지갑 열기${icon('arrow')}</button></section></div><section class="pick-section"><div class="section-heading"><div class="section-title-group"><span class="section-index">01</span><h2>나를 위한 정책 픽</h2></div><button class="text-button" data-action="all-policies">정책 모두 보기${icon('arrow')}</button></div><div class="home-policy-grid">${policies.map(card).join('')}</div>${demoNote()}</section><section class="home-change"><div><h3>졸업하거나, 이사하면 내 정책은 어떻게 달라질까?</h3><p>내 정보는 그대로 두고, 변화 후 조건을 미리 비교해 봐요.</p></div><button class="button" data-route="switch">변화 비교하기${icon('arrow')}</button></section>`+footer();};
const coreFiltered=filteredPolicies;
filteredPolicies=function(){let arr=coreFiltered().filter(p=>(!savedFilter||extra.saved.includes(p.id))&&(regionFilter==='전체'||(regionFilter==='전국'?p.id===2:p.id!==2))&&(studentFilter==='전체'||({1:['대학 재학','졸업','구직 중'],2:['대학 재학','졸업','구직 중'],3:['대학 재학','휴학','구직 중']})[p.id].includes(studentFilter))&&(recruitFilter!=='모집 중'));if(purpose==='독립 준비')arr=arr.filter(p=>p.cat==='주거');if(purpose==='취업 준비')arr=arr.filter(p=>['교육','일자리'].includes(p.cat));if(purpose==='교육·자격')arr=arr.filter(p=>p.cat==='교육');if(purpose==='창업 준비')arr=arr.filter(p=>p.cat==='창업');return arr;};
emptyResults=function(){return `<div class="empty-state"><span class="new-empty-mark" aria-hidden="true">N</span><h3>지금 조건에는 연결된 정책이 없어요.</h3><p>시연 정책은 3개예요. 지역·학적·분야 조건을 넓혀 다시 살펴볼까요?</p><button class="button lime" data-action="reset-filters">조건 넓혀 보기${icon('arrow')}</button></div>`;};
function nextPolicySearch(){return `<form class="search-form" id="policySearchForm" role="search">${icon('search')}<input type="search" name="search" autocomplete="off" maxlength="100" aria-label="정책명 또는 관심 분야 검색" placeholder="주거, 취업, 교육… 어떤 다음을 찾고 있나요?" value="${esc(searchTerm)}"><button type="button" class="search-clear" data-action="clear-search" aria-label="검색어 지우기" ${searchTerm?'':'hidden'}>${icon('close')}</button><button class="search-submit" type="submit">검색</button></form>`;}
policiesPage=function(){const p=state.profile;return crumb('정책 찾기')+pageIntro('FIND YOUR NEXT','지금 내게 필요한, 한 장.','정책 이름을 몰라도 괜찮아요. 내 생활권과 목적부터 살펴봐요.',`<button class="button" data-next-action="saved-policies">${simpleIcon('bookmark')}${savedFilter?'전체 정책 보기':`저장한 정책 ${extra.saved.length}`}</button>`)+`${nextPolicySearch()}<div class="new-policy-tools"><span>이런 다음은 어때요?</span>${['대학생','취업 준비','독립 준비','교육·자격','창업 준비'].map(v=>`<button class="purpose-pick ${purpose===v?'active':''}" data-purpose="${v}" aria-pressed="${purpose===v}">${v}</button>`).join('')}<button class="text-button" data-next-question="천안에서 학교를 다니는데 경기도에 살아요">내 상황으로 물어보기 ↗</button></div><div class="condition-row"><span>내 조건</span>${[`만 ${p.age}세`,p.status,`거주 ${p.residence}`,`학교 ${p.school||'해당 없음'}`].map(t=>`<button class="condition-pill" data-route="profile">${esc(t)} ›</button>`).join('')}<span>직접 입력</span></div><button class="policy-filter-toggle" data-next-action="filter-toggle" aria-expanded="${filtersExpanded}" aria-controls="policyFilter">${icon('filter')}상세 조건</button><div class="policy-explorer"><aside class="policy-filter ${filtersExpanded?'open':''}" id="policyFilter"><h3>조금 더 나에게 맞게</h3><div class="filter-fields">${[['region','생활권',['전체','천안 생활권','전국'],regionFilter],['student','현재 상태',['전체',...profileStatuses],studentFilter],['recruit','모집 상태',['전체','공고 확인 필요','모집 중'],recruitFilter]].map(([key,label,values,value])=>`<label>${label}<select data-next-filter="${key}" aria-label="${label} 필터">${selectOptions(values,value)}</select></label>`).join('')}</div><button class="text-button" data-action="reset-filters">조건 초기화 ↺</button><p>생활권은 탐색 기준이에요. 지원 자격은 정책별 공고에서 확인해요.</p></aside><section>${categories()}${statusFilter!=='all'?'<button class="preset active" data-action="clear-status">추가 확인 필터 해제 ×</button>':''}<div class="filters-head"><span>찾은 정책 <b id="resultCount" aria-live="polite">${filteredPolicies().length}</b>개 <small style="display:block;font-size:10px;color:var(--muted);margin-top:4px">${esc(regionFilter)} · ${esc(studentFilter)} 기준으로 보고 있어요.</small></span><select id="sortSelect" class="filter-sort" aria-label="정렬 기준"><option value="related" ${sort==='related'?'selected':''}>기본순</option><option value="name" ${sort==='name'?'selected':''}>정책명순</option></select></div><div class="policy-list" id="policyResults">${resultsHTML()}</div>${demoNote('시연용 정책 목록이에요. 실제 공고와 연결되기 전까지 모집 상태는 확인 필요로 표시해요.')}</section></div>`+footer();};
function criteriaRows(){const p=state.profile;return [['연령','공고의 연령·기준일 확인',`만 ${p.age}세`],['생활권','주민등록·재학·근무 인정 범위',`${p.residence} 거주 / 학교 ${p.school||'없음'}`],['학적·취업','재학생·구직자 참여 범위',p.status],['소득·이력','가구·소득·중복수혜 기준','입력·문서 확인 전']];}
function sourceModal(label='공고'){openDialog(`${label}, 어디까지 확인했나요?`,`<span class="badge check">공식 공고 미연결</span><p style="margin-top:16px">현재 정책은 화면 흐름을 보여 주는 시연 예시예요. 실제 기준·적용 기준일·원문 근거는 아직 연결되지 않았어요.</p><div class="issuance-note"><strong>공고에서 확인할 것</strong><p>시행기관 · 모집 기간 · 연령 기준일 · 주민등록·재학·근무 지역 · 소득·중복수혜 · 제출 서류</p></div><a class="button primary full" href="https://www.youthcenter.go.kr/" target="_blank" rel="noopener noreferrer">온통청년에서 정책 찾기 ↗</a><button class="text-button" data-download="0">공고 확인 기록표 받기${simpleIcon('download')}</button>`);}
detail=function(id){const p=getPolicy(id);return crumb('정책 상세')+`<button class="text-button back-button" data-route="policies">${icon('back')}정책 목록으로</button><section class="detail-head new-detail-head" data-category="${p.cat}"><span class="badge neutral">${p.cat} · 시연 예시</span><h1>${p.title}</h1><p>${p.desc}</p><div class="detail-meta"><span>모집 상태<strong>공고 확인 필요</strong></span><span>지원 내용<strong>공고 연결 후 확인</strong></span></div></section><div class="content-two detail-grid"><section><div class="surface panel"><div class="criteria-heading"><h2>공고 기준과 나의 조건</h2><span class="badge check">추가 확인</span></div><p class="panel-description" style="margin-bottom:20px">${p.explanation}</p><table class="next-table"><thead><tr><th scope="col">항목</th><th scope="col">공고 기준</th><th scope="col">내 정보</th><th scope="col">확인 결과</th><th scope="col">근거</th></tr></thead><tbody>${criteriaRows().map(([l,r,v])=>`<tr><td>${l}</td><td>${r}</td><td>${esc(v)}<br><small class="subtle">직접 입력</small></td><td><span class="badge check">추가 확인</span></td><td><button class="text-button" data-next-source="${l}">공고 연결 전 ›</button></td></tr>`).join('')}</tbody></table><p class="next-source-line">공식 출처 · 미연결 / 적용 기준일 · 확인 전 / 마지막 공고 확인 · 기록 없음</p></div><section class="surface panel"><h2>미리 살펴볼 준비 서류</h2>${walletDocuments.map(d=>`<button class="doc-needed" data-wallet-issuance="${d.id}">${icon('file')}<span>${d.name}</span><small>기준 확인 ›</small></button>`).join('')}<div style="margin-top:16px">${demoNote('실제 제출 종류와 발급 기준일은 공고에서 확인해요.')}</div></section></section><aside><section class="surface side-panel action-panel"><span class="mono-kicker">ONE MORE STEP</span><h2>알아본 정책,<br>내 준비로 이어가요.</h2><p>공고 확인부터 서류 점검까지.<br>다음 해야 할 일을 한 칸씩 모아드려요.</p><button class="button lime full" data-prepare="${p.id}">${state.preparedPolicy===p.id?'준비 이어가기':'이 정책 준비하기'}${icon('arrow')}</button><button class="text-button" data-policy-save="${p.id}" style="margin-top:15px">${simpleIcon('bookmark')}${extra.saved.includes(p.id)?'저장 취소':'나중에 볼 정책으로 저장'}</button></section><section class="surface side-panel"><h3>이 조건이 헷갈린다면?</h3><p style="margin-top:10px;font-size:12px;color:var(--muted)">내비게이터에게 쉬운 말로 물어봐요.</p><button class="text-button" style="margin-top:15px" data-next-question="${p.title}의 지역 조건을 설명해줘">AI에게 물어보기${icon('arrow')}</button></section></aside></div>`+footer();};
function scenarioFields(){const regionValues=['경기도','천안시','아산시','서울특별시','충청남도','기타'];return [['residence','주민등록지',regionValues],['school','학교 소재지',['',...regionValues]],['status','학적 상태',profileStatuses],['employment','취업 상태',['구직 중','재직 중','창업','해당 없음']]].map(([k,l,a])=>`<div class="scenario-field"><label for="future-${k}">${l}</label><select id="future-${k}" data-future-field="${k}">${selectOptions(a,future[k])}</select></div>`).join('');}
function differenceRows(){if(!scenarioSnapshot)return[];const p=scenarioSnapshot.before,f=scenarioSnapshot.after;return [['주민등록지',p.residence,f.residence],['학교 소재지',p.school||'해당 없음',f.school||'해당 없음'],['학적·현재 상태',p.status,f.status],['취업 상태',['구직 중','재직 중','창업'].includes(p.status)?p.status:'확인 전',f.employment]];}
function scenarioResults(){const rows=differenceRows(),changed=rows.filter(r=>r[1]!==r[2]),impacted=new Set();for(const [l]of changed){if(l.includes('지역')||l==='주민등록지'||l==='학교 소재지'){impacted.add(1);impacted.add(3);}else{impacted.add(2);impacted.add(3);}}return `<div class="section-heading"><div><h2>${changed.length}가지 조건이 달라져요.</h2><p class="section-caption">달라진 조건을 보고, 연결된 공고의 기준을 다시 확인해요.</p></div><label style="font-size:10px;display:flex;gap:6px;align-items:center"><input id="changedOnly" type="checkbox" ${onlyChanged?'checked':''}>변경 항목만</label></div><section class="surface panel"><table class="comparison"><thead><tr><th scope="col">조건</th><th scope="col">현재</th><th scope="col">변화 후</th></tr></thead><tbody>${rows.filter(r=>!onlyChanged||r[1]!==r[2]).map(([k,a,b])=>`<tr><td>${k}</td><td>${esc(a)}</td><td class="${a!==b?'changed':''}">${esc(b)}${a!==b?'<span class="change-label">변경</span>':''}</td></tr>`).join('')||'<tr><td colspan="3">달라진 항목이 없어요.</td></tr>'}</tbody></table></section><h3>다시 살펴볼 정책</h3>${policies.filter(p=>impacted.has(p.id)).map(p=>`<div class="scenario-policy"><div><strong>${p.title}</strong><small>${p.reason} 재확인 필요</small></div><button class="text-button" data-policy="${p.id}">조건 보기${icon('arrow')}</button></div>`).join('')||'<p class="quiet-note">현재와 같은 조건이에요.</p>'}`;}
switchPage=function(){const p=state.profile;return crumb('생활변화 비교')+pageIntro('A LITTLE CHANGE, A NEW POSSIBILITY','내일의 나에게, 어떤 다음이?','지역·학적·취업 상태를 나눠 바꾸고 영향을 받을 조건을 살펴봐요.')+`<div class="scenario-info">${icon('switch')}<div><strong>가정한 상황만 비교해요.</strong><p>이곳의 선택은 실제 내정보에 저장되지 않아요. 가능 여부는 각 공고를 다시 확인해요.</p></div></div><div class="scenario-picks">${[['graduate','졸업 후 구직'],['move','천안으로 전입'],['both','졸업 + 천안 전입']].map(([k,l])=>`<button class="purpose-pick" data-next-preset="${k}">${l} ↗</button>`).join('')}</div><div class="scenario-columns"><section class="scenario-block"><span class="mono-kicker">BEFORE / 현재 내 정보</span><h2>지금의 나</h2><div class="scenario-fields">${[['주민등록지',p.residence],['학교 소재지',p.school||'해당 없음'],['학적·현재 상태',p.status],['근무 지역',p.workRegion||'해당 없음']].map(([l,v])=>`<div class="scenario-field"><label>${l}</label><div class="scenario-current">${esc(v)}</div></div>`).join('')}</div><button class="text-button" data-route="profile" style="margin-top:20px">현재 내 정보 수정${icon('arrow')}</button></section><span class="scenario-direction" aria-hidden="true">${icon('arrow')}</span><section class="scenario-block after"><span class="mono-kicker">AFTER / 가정한 상황</span><h2>변화 후의 나</h2><div class="scenario-fields">${scenarioFields()}</div></section></div><div class="scenario-run">${demoNote('가정한 상황이에요. 실제 자격 변화·예상 지원금은 공식 기준 확인 전까지 판정하지 않아요.')}<button class="button lime" data-next-action="scenario-run">이 조건으로 비교하기${icon('arrow')}</button></div><section id="scenarioResults" class="scenario-diffs">${scenarioSnapshot?scenarioResults():''}</section>`+footer();};
const taskActions=[['공고 열기','source'],['조건 표 보기','criteria'],['발급처 확인','issue'],['준비표 받기','template'],['제출 안내','submission-guide']];
function calendarHTML(){const base=extra.goal?new Date(extra.goal+'T12:00:00'):new Date(dateISO()+'T12:00:00');base.setMonth(base.getMonth()+calendarOffset,1);const y=base.getFullYear(),m=base.getMonth(),start=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate();return `<section class="surface panel"><div class="section-heading"><button class="text-button" data-calendar-shift="-1" aria-label="이전 달">←</button><h3>${y}년 ${m+1}월</h3><button class="text-button" data-calendar-shift="1" aria-label="다음 달">→</button></div>${demoNote('내가 설정한 준비 목표일이에요. 공식 신청 일정은 아직 연결되지 않았어요.')}<div class="new-calendar">${['일','월','화','수','목','금','토'].map(d=>`<span class="calendar-weekday">${d}</span>`).join('')}${Array.from({length:start},()=>'<span></span>').join('')}${Array.from({length:days},(_,i)=>{const day=`${y}-${pad(m+1)}-${pad(i+1)}`;return `<div class="calendar-day ${day===extra.goal?'goal':''}">${i+1}${day===extra.goal?'<small>나의 준비<br>목표일</small>':''}</div>`;}).join('')}</div></section>`;}
applyPage=function(){const p=getPolicy(state.preparedPolicy),done=state.completed.size,step=done===5?3:done>=2?2:done>=1?1:0;return crumb('신청 준비')+pageIntro('ONE STEP CLOSER','다음 한 칸씩, 준비해요.','진행 중인 준비와 필요한 문서, 나의 목표일을 함께 살펴봐요.')+`<section class="surface prep-overview new-prep-overview"><div><span class="mono-kicker">MY ONGOING PICK</span><h2>${p.title}</h2><p class="section-caption">다음 행동 · ${done===5?'공식 제출 여부 확인':taskActions[taskList.findIndex((_,i)=>!state.completed.has(i))][0]}</p></div><div class="prep-progress"><div class="progress-label"><span>준비 점검 ${done}/5</span><strong>${done*20}%</strong></div><div class="progress-track" role="progressbar" aria-label="준비 점검 진행률" aria-valuenow="${done*20}" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill" style="width:${done*20}%"></div></div><p class="section-caption" style="font-size:10px">준비 완료와 공식 제출은 별도로 확인해요.</p></div></section><div class="prep-step-strip">${['공고 확인','내 조건 확인','서류 준비','제출 확인'].map((l,i)=>`<div class="prep-stage ${i<step?'complete':i===step?'active':''}"><span>${i<step?'✓':pad(i+1)}</span>${l}</div>`).join('')}</div><div class="section-heading"><h2>나의 준비 노트</h2><div class="category-tabs">${[['list','목록'],['calendar','달력']].map(([k,l])=>`<button class="category-tab ${prepMode===k?'active':''}" data-next-prep="${k}" aria-pressed="${prepMode===k}">${l}</button>`).join('')}</div></div><div class="content-two prep-grid"><section>${prepMode==='calendar'?calendarHTML():`<div class="surface panel">${taskList.map((t,i)=>`<div class="task-row"><div class="task-main"><input type="checkbox" id="task-${i}" data-task="${i}" ${state.completed.has(i)?'checked':''}><label class="task-label" for="task-${i}"><strong>${i===4?'제출 전 최종 점검':t.title}</strong><small>${i===4?'신청서와 첨부파일, 제출 경로를 살펴봐요.':t.desc}</small></label><span class="badge ${state.completed.has(i)?'good':'neutral'}">${state.completed.has(i)?'직접 점검':'할 일'}</span></div><div class="next-task-actions"><button class="text-button" data-next-task="${taskActions[i][1]}">${taskActions[i][0]}${icon('arrow')}</button><button class="small-action" data-save="${i}" ${state.wallet.has(i)?'disabled':''}>${state.wallet.has(i)?'안내 양식 보관 중':'안내 양식 보관'}</button></div></div>`).join('')}</div>`}${demoNote('체크는 내가 점검한 기록이에요. 공식 자격 판정·서류 검증·접수 완료를 의미하지 않아요.')}</section><aside><section class="next-calendar-box"><span class="mono-kicker">MY TARGET DATE</span><h3>나의 준비 목표일</h3><p>공식 마감과 구분되는, 내가 정한 일정이에요.</p><form id="nextGoalForm" class="goal-form"><label class="sr-only" for="nextGoal">준비 목표일</label><input type="date" id="nextGoal" name="goal" value="${esc(extra.goal)}" required><button class="button" type="submit">저장</button></form><div class="goal-summary"><span>목표일</span><strong>${displayDate(extra.goal)}</strong></div><p style="margin-top:10px">공식 신청 마감 · 공고 연결 후 확인</p>${extra.goal?'<button class="text-button" style="font-size:10px;margin-top:10px" data-next-action="clear-goal">목표일 지우기 ↺</button>':''}</section><section class="submission-card"><span class="badge ${extra.submitted?'good':'check'}">${extra.submitted?'본인 확인 기록':'공식 제출 미확인'}</span><h3>${extra.submitted?'제출한 기록을 남겼어요.':'마지막은, 공식 제출 확인.'}</h3><p>${extra.submitted?'본인이 확인한 접수 기록이에요. '+esc(extra.receipt):'공식 신청 페이지에서 제출한 뒤 접수 내역을 확인해요.'}</p><button class="button full" data-next-action="submission">${extra.submitted?'제출 기록 보기':'제출 여부 기록하기'}${icon('arrow')}</button></section>${walletPanel()}</aside></div>`+footer();};
function submissionModal(){openDialog('공식 제출 여부 기록하기',`<p>공식 페이지에서 제출·접수 내역을 본인이 확인한 기록이에요. 청년픽이 제출하거나 접수 상태를 검증하는 기능은 아니에요.</p><form id="nextSubmissionForm"><label class="field-label" for="nextReceipt" style="margin-top:20px">나만의 접수 메모 <span class="subtle">선택</span></label><input class="field" id="nextReceipt" name="receipt" maxlength="100" value="${esc(extra.receipt)}" placeholder="예: 공식 페이지의 접수 내역 확인"><label style="display:flex;gap:8px;font-size:12px;margin-top:20px"><input type="checkbox" name="confirmed" ${extra.submitted?'checked':''}>공식 페이지에서 제출·접수 내역을 직접 확인했어요.</label><button class="button lime full" type="submit" style="margin-top:22px">내 확인 기록 저장${icon('check')}</button></form>`);}
const coreWalletPanel=walletPanel;
walletPanel=function(){return coreWalletPanel().replace('실제 증빙서류는 업로드하지 않아요.','직접 추가한 문서는 전자지갑 전체 화면에서 확인해요.')+`<p class="quiet-note" style="margin-top:-7px;margin-bottom:20px">내 기기에 직접 보관한 문서 ${liveFiles().length}개 · 외부 지갑 미연결</p>`;};
const coreProfile=profilePage;
profilePage=function(){return crumb('내 정보')+coreProfile().replace('나를 알아야, 픽도 정확하게.','나를 알아야, 더 잘 고르니까.').replace('정책을 살펴보는 데 필요한 정보만 입력해요.','추천에 사용할 내 조건과 준비 문서를 함께 관리해요.');};
const coreProfileWallet=profileWalletPreview;
profileWalletPreview=function(){return coreProfileWallet().replace('증명서 연결 <strong>0</strong>',`내 기기 문서 <strong>${liveFiles().length}</strong>`).replace('카카오·네이버 연결 화면을 미리 볼 수 있어요.','외부 지갑은 미연결 · 직접 보관 문서는 별도 검증이 필요해요.');};
const filesDb=new Promise((resolve,reject)=>{try{const r=indexedDB.open('cheongnyeonpick-next-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);}catch(e){reject(e);}});filesDb.catch(()=>{});
async function writeFile(id,file){const db=await filesDb;return new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(file,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
async function readFile(id){const db=await filesDb;return new Promise((resolve,reject)=>{const r=db.transaction('files').objectStore('files').get(id);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
const fileInput=document.createElement('input');fileInput.type='file';fileInput.multiple=true;fileInput.accept='.pdf,.png,.jpg,.jpeg,.txt,.docx';fileInput.hidden=true;fileInput.id='nextFileInput';fileInput.setAttribute('aria-label','보관할 문서 선택');document.body.append(fileInput);
fileInput.addEventListener('change',async()=>{let added=0;for(const f of [...fileInput.files]){if(f.size>15*1024*1024){toast('파일당 15MB까지 보관할 수 있어요.');continue;}if(!/\.(pdf|png|jpe?g|txt|docx)$/i.test(f.name)){toast('PDF·이미지·TXT·DOCX 파일을 선택해 주세요.');continue;}const id=crypto.randomUUID();try{await writeFile(id,f);extra.files.push({id,name:f.name,type:f.type,size:f.size,date:dateISO(),policy:state.preparedPolicy,archived:false});walletUI.selected=id;added++;}catch(_){toast('이 브라우저에 파일을 보관하지 못했어요. 저장 공간과 권한을 확인해 주세요.');}}fileInput.value='';if(added){saveExtra();walletUI.tab='files';walletUI.query='';showArchived=false;go('wallet');savedFeedback(`${added}개 문서를 이 기기에 보관했어요. 발급 여부는 별도 확인이 필요해요.`);}});
function filePanel(){const q=walletUI.query.trim().toLocaleLowerCase();const list=extra.files.filter(d=>d.archived===showArchived&&(!q||d.name.toLocaleLowerCase().includes(q)));const d=list.find(d=>d.id===walletUI.selected)||list[0];if(d)walletUI.selected=d.id;return `<div class="wallet-tools"><label class="wallet-search">${icon('search')}<input id="walletSearch" type="search" aria-label="전자지갑 서류 검색" placeholder="보관한 문서 이름으로 찾아보세요" value="${esc(walletUI.query)}"></label><button class="purpose-pick ${showArchived?'active':''}" data-next-action="show-archived">${showArchived?'보관 중인 문서 보기':'보관 해제 내역'}</button></div><div class="wallet-document-grid"><section class="wallet-list-area"><div class="wallet-list-heading"><h2>${showArchived?'보관 해제한 문서':'내 기기에 보관한 문서'} <span>${list.length}</span></h2></div><p class="wallet-list-description">파일 보관과 발급기관·유효성 검증, 공식 제출은 별도예요.</p>${list.length?list.map(f=>`<div class="file-list-row">${icon('file')}<div style="min-width:0;flex:1"><strong>${esc(f.name)}</strong><small>${displayDate(f.date)} · ${Math.max(1,Math.ceil(f.size/1024))}KB · 검증 전</small><small>${getPolicy(f.policy).title}</small><div class="file-actions"><button data-next-file="${esc(f.id)}" data-file-action="select">정보 보기</button><button data-next-file="${esc(f.id)}" data-file-action="download">받기</button><button data-next-file="${esc(f.id)}" data-file-action="archive">${showArchived?'복원':'보관 해제'}</button></div></div></div>`).join(''):`<div class="wallet-list-empty"><span class="new-empty-mark">N</span><h3>${q?'찾는 문서가 없어요.':showArchived?'보관 해제한 문서가 없어요.':'아직 모아 둔 문서가 없어요.'}</h3><p>${q?'검색어를 줄이거나 조건을 초기화해 보세요.':'필요한 서류를 확인한 뒤 파일을 직접 추가해 보세요.'}</p><button class="button" ${q?'data-wallet-reset':'data-next-action="upload"'}>${q?'검색 조건 초기화':'문서 추가'}${icon('arrow')}</button></div>`}</section><aside class="wallet-document-detail"><div class="wallet-detail-topline"><span>MY DOCUMENT</span><span>LOCAL</span></div><div class="wallet-document-preview lilac"><div class="document-paper"><span class="paper-title">내 기기 문서</span><span class="paper-line long"></span><span class="paper-line"></span><span class="paper-stamp">검증 전</span></div></div>${d?`<h3 class="wallet-detail-title">${esc(d.name)}</h3><p class="wallet-detail-state">발급기관·유효성 확인 전</p><dl class="wallet-detail-meta"><div><dt>보관일</dt><dd>${displayDate(d.date)}</dd></div><div><dt>보관 방식</dt><dd>이 기기에서 직접 추가</dd></div><div><dt>발급 기준</dt><dd>공고 확인 필요</dd></div></dl><label class="field-label" style="font-size:11px" for="filePolicy">연결해서 준비할 정책</label><select id="filePolicy" class="file-policy-link" data-file-policy="${esc(d.id)}">${policies.map(p=>`<option value="${p.id}" ${p.id===d.policy?'selected':''}>${p.title}</option>`).join('')}</select><button class="button wallet-dark full" style="margin-top:15px" data-next-file="${esc(d.id)}" data-file-action="download">문서 받기${simpleIcon('download')}</button><button class="text-button" data-policy="${d.policy}" style="margin-top:10px">연결 정책 조건 보기${icon('arrow')}</button>`:'<h3 class="wallet-detail-title">문서의 쓰임까지, 한눈에.</h3><p class="wallet-detail-state">문서를 추가하면 준비할 정책과 연결할 수 있어요.</p>'}</aside></div>`;}
walletTabs=function(){return `<div class="wallet-tabs" role="tablist" aria-label="전자지갑 자료">${[['documents','필요한 서류',walletDocuments.length],['guides','안내 양식',state.wallet.size],['files','내 문서',liveFiles().length],['activity','확인 기록',walletUI.history.length]].map(([k,l,n])=>`<button id="wallet-tab-${k}" role="tab" aria-selected="${walletUI.tab===k}" aria-controls="wallet-tabpanel" tabindex="${walletUI.tab===k?'0':'-1'}" class="wallet-tab ${walletUI.tab===k?'active':''}" data-wallet-tab="${k}">${l}<span>${n}</span></button>`).join('')}</div>`;};
walletWorkspace=function(){return `<section class="wallet-workspace" aria-label="내 서류 작업 공간">${walletTabs()}<div id="wallet-tabpanel" role="tabpanel" aria-labelledby="wallet-tab-${walletUI.tab}" tabindex="0">${walletUI.tab==='activity'?walletActivity():walletUI.tab==='files'?filePanel():walletDocumentsPanel()}</div><div class="new-files-upload"><div><p>준비한 파일을 보관하고, 필요한 정책에 연결해요.</p><small>PDF · 이미지 · TXT · DOCX / 파일당 15MB / 현재 기기의 브라우저에 저장</small></div><button class="button lime" data-next-action="upload">${simpleIcon('plus')}문서 추가</button></div></section>`;};
const oldWalletPage=walletPage;
walletPage=function(){const box=document.createElement('div');box.innerHTML=oldWalletPage();const intro=box.querySelector('h1');if(intro)intro.textContent='준비는 한곳에. 쓰임은 한눈에.';const first=box.querySelector('.wallet-summary>div');if(first){first.querySelector('span').textContent='내 기기 보관 문서';first.querySelector('strong').innerHTML=pad(liveFiles().length)+'<small>개</small>';first.querySelector('em').textContent='발급 여부 별도 확인';}return crumb('전자지갑')+box.innerHTML;};
const oldNavigatorAnswer=navigatorAnswer;
navigatorAnswer=function(kind){const a=oldNavigatorAnswer(kind);if(kind==='region'){a.route='detail/1';a.action='지역 조건 표 확인하기';}a.conditions=[`주민등록 · ${state.profile.residence}`,`학교 · ${state.profile.school||'미입력'}`,`현재 · ${state.profile.status}`];return a;};
navigatorMark=function(){return '<svg class="navigator-mark" viewBox="0 0 32 32" aria-hidden="true"><path d="m16 2 4 9 10 5-10 5-4 9-5-9-9-5 9-5Z" fill="#ddf580" stroke="currentColor" stroke-width="1"/><path d="M12 21V11l8 10V11" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>';};
navigatorThread=function(){if(!navigatorUI.messages.length)return `<div class="navigator-welcome"><p class="mono-kicker">A LITTLE HELP FOR YOUR NEXT</p><h3>다음 한 칸,<br><span>같이 찾아볼까요?</span></h3><p>어려운 정책 말 대신, 지금 내 상황부터.<br>조건을 풀어 보고, 할 일로 이어가요.</p></div><div class="navigator-suggestions"><button data-next-question="천안 대학생의 주거 조건이 궁금해요">천안 대학생의 주거 조건이 궁금해요${icon('arrow')}</button><button data-navigator-prompt="documents">신청 전에 준비할 서류를 정리해줘${icon('arrow')}</button><button data-next-question="졸업하고 천안으로 이사하면?">졸업하고 천안으로 이사하면?${icon('arrow')}</button></div><div class="navigator-followups" style="margin-top:13px"><button data-navigator-prompt="connect">지갑 연결 ↗</button><button data-navigator-prompt="next">다음 준비 ↗</button></div><p class="quiet-note" style="font-size:10px;margin-top:20px">현재 화면과 내 조건을 참고하는 시연 대화예요. 실시간 AI 생성·개별 공고 연결은 아직 제공하지 않아요.</p>`;return navigatorUI.messages.map(m=>m.user?`<div class="navigator-user-message">${esc(m.user)}</div>`:`<div class="navigator-answer"><span class="answer-brand">NEXT NAVIGATOR · 시연 응답</span><h3>${esc(m.title)}</h3><p>${esc(m.text)}</p><div class="navigator-interpreted"><strong>현재 참고한 조건</strong>${(m.conditions||[]).map(c=>`<span>${esc(c)}</span>`).join('')}<button data-navigator-go="profile">조건과 내 정보 확인 ›</button></div><div class="navigator-source-note"><strong>근거 상태 · 개별 공고 미연결</strong><br>아래는 공고 원문이 아닌 직접 확인할 공식 서비스예요.<br><a href="https://www.youthcenter.go.kr/" target="_blank" rel="noopener noreferrer">온통청년 ↗</a><a href="https://www.gov.kr/" target="_blank" rel="noopener noreferrer">정부24 ↗</a></div><button data-navigator-go="${m.route}" ${m.doc?'data-navigator-doc="'+m.doc+'"':''}>${esc(m.action)}${icon('arrow')}</button></div>`).join('')+'<div class="navigator-followups"><button data-navigator-prompt="documents">필요한 서류</button><button data-navigator-prompt="connect">지갑 연결</button><button data-navigator-prompt="next">다음 준비</button></div>';};
const oldClassify=classifyNavigator;
classifyNavigator=function(text){if(/소득|건강보험|금액증명/.test(text))return'income';if(/연결|연동|카카오|네이버/.test(text))return'connect';if(/변화|졸업|전입|이사/.test(text))return'switch';if(/서류|증명|지갑/.test(text))return'documents';if(/주거|대학생|천안|집|거주|지역|주소|생활권|학교/.test(text))return'region';return oldClassify(text);};
for(const cls of ['.launcher-icon','.navigator-header-mark'])if($(cls))$(cls).innerHTML=navigatorMark();
if($('.navigator-header p'))$('.navigator-header p').textContent='NEXT NAVIGATOR · 시연 대화';
if($('.navigator-disclosure'))$('.navigator-disclosure').textContent='시연 안내 · 실시간 AI 생성과 개별 공고 연결은 아직 제공하지 않아요.';
function compareDock(){document.querySelector('.comparison-dock')?.remove();if(!compare.length||!['home','policies'].includes(currentRoute().page))return;const d=document.createElement('aside');d.className='comparison-dock';d.setAttribute('aria-label','정책 비교 선택');d.innerHTML=`<span>선택한 정책 <strong>${compare.length}</strong>개</span><button class="button" data-next-action="compare" ${compare.length<2?'disabled':''}>나란히 비교${icon('arrow')}</button><button class="text-button" data-next-action="clear-compare">비우기</button>`;document.body.append(d);}
function compareModal(){const ps=compare.map(getPolicy);openDialog('내가 고른 정책, 나란히.',`<p>차이를 살펴보는 시연 비교예요. 실제 혜택과 자격은 공고 확인이 필요해요.</p><table class="comparison" style="margin-top:20px;table-layout:fixed"><thead><tr><th scope="col">비교 항목</th>${ps.map(p=>`<th scope="col">${p.title}</th>`).join('')}</tr></thead><tbody>${[['지원 내용',p=>p.desc],['모집 기간',()=>'공고 확인 필요'],['지역 기준',p=>p.reason],['연령·소득',()=>'공고 기준 확인 필요'],['중복수혜',()=>'세부 조건 확인 필요'],['준비 서류',()=>'공고의 제출서류 확인']].map(([label,f])=>`<tr><td>${label}</td>${ps.map(p=>`<td>${f(p)}</td>`).join('')}</tr>`).join('')}</tbody></table>`);$('#infoDialog').classList.add('compare-dialog');}
const coreRender=render;
render=function(reset=false){coreRender(reset);compareDock();if(navigatorUI.open)updateNavigatorThread();if(currentRoute().page==='profile')$('#profileForm')?.setAttribute('novalidate','');};
function refreshAtSamePosition(){const y=scrollY;render();window.scrollTo({top:y,behavior:'instant'});}
function resetExtraFilters(){purpose='';regionFilter='전체';studentFilter='전체';recruitFilter='전체';savedFilter=false;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.action==='reset-filters'||b.dataset.action==='all-policies'||b.dataset.overview)resetExtraFilters();if(b.dataset.prepare&&Number(b.dataset.prepare)!==state.preparedPolicy){extra.goal='';extra.submitted=false;extra.receipt='';saveExtra();}},true);
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.nextQuestion){const q=b.dataset.nextQuestion;askNavigator(classifyNavigator(q),q);return;}
 if(b.dataset.policySave){const id=Number(b.dataset.policySave);extra.saved=extra.saved.includes(id)?extra.saved.filter(x=>x!==id):[...extra.saved,id];saveExtra();refreshAtSamePosition();savedFeedback(extra.saved.includes(id)?'나중에 볼 정책에 저장했어요.':'정책 저장을 취소했어요.');return;}
 if(b.dataset.purpose){purpose=purpose===b.dataset.purpose?'':b.dataset.purpose;refreshAtSamePosition();return;}
 if(b.dataset.nextSource!==undefined){sourceModal(b.dataset.nextSource);return;}
 if(b.dataset.nextPreset){future={residence:state.profile.residence,school:state.profile.school,status:state.profile.status,employment:state.profile.status==='재직 중'?'재직 중':'구직 중'};if(b.dataset.nextPreset!=='move')future.status='졸업';if(b.dataset.nextPreset!=='graduate')future.residence='천안시';scenarioSnapshot=null;render();toast('가정한 조건을 입력했어요. 비교 버튼을 눌러 살펴봐요.');return;}
 if(b.dataset.nextPrep){prepMode=b.dataset.nextPrep;refreshAtSamePosition();return;}
 if(b.dataset.calendarShift){calendarOffset+=Number(b.dataset.calendarShift);refreshAtSamePosition();return;}
 if(b.dataset.nextTask){switch(b.dataset.nextTask){case'source':sourceModal();break;case'criteria':go('detail/'+state.preparedPolicy);break;case'issue':showIssuance('student');break;case'template':downloadTaskFile(3);break;case'submission-guide':openDialog('준비를 마쳤다면, 공식 페이지로.',`<p>공식 공고의 신청 경로에서 실제 제출을 진행하고 접수 내역을 확인해요.</p><div class="issuance-note"><strong>제출 전 한 번 더</strong><p>신청 기간 · 필수 입력값 · 첨부파일 형식·용량 · 최종 제출 버튼 · 접수 내역</p></div><button class="button lime full" data-next-action="submission">제출 여부 기록하기${icon('arrow')}</button>`);break;}return;}
 if(b.dataset.nextFile){const d=extra.files.find(f=>f.id===b.dataset.nextFile);if(!d)return;switch(b.dataset.fileAction){case'select':walletUI.selected=d.id;refreshAtSamePosition();if(innerWidth<601)document.querySelector('.wallet-document-detail')?.scrollIntoView({behavior:'smooth',block:'start'});break;case'archive':d.archived=!d.archived;saveExtra();refreshAtSamePosition();savedFeedback(d.archived?'보관 해제했어요. 보관 해제 내역에서 복원할 수 있어요.':'문서를 다시 보관했어요.');break;case'download':try{const file=await readFile(d.id);if(!file)throw new Error('missing');const u=URL.createObjectURL(file),a=document.createElement('a');a.href=u;a.download=d.name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),15000);toast('보관한 문서를 내려받았어요.');}catch(_){toast('이 기기에서 파일을 찾지 못했어요. 문서를 다시 추가해 주세요.');}break;}return;}
 switch(b.dataset.nextAction){case'saved-policies':savedFilter=!savedFilter;render();break;case'filter-toggle':filtersExpanded=!filtersExpanded;refreshAtSamePosition();break;case'compare':compareModal();break;case'clear-compare':compare=[];render();break;case'scenario-run':scenarioSnapshot={before:{...state.profile},after:{...future}};$('#scenarioResults').innerHTML=scenarioResults();$('#scenarioResults').scrollIntoView({behavior:'smooth',block:'start'});toast('가정한 조건을 비교했어요. 실제 내정보는 그대로예요.');break;case'clear-goal':extra.goal='';calendarOffset=0;saveExtra();refreshAtSamePosition();toast('나의 준비 목표일을 지웠어요.');break;case'submission':submissionModal();break;case'upload':$('#infoDialog').close();fileInput.click();break;case'show-archived':showArchived=!showArchived;refreshAtSamePosition();break;}
});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.policyCompare){const id=Number(el.dataset.policyCompare);compare=el.checked?[...new Set([...compare,id])].slice(0,3):compare.filter(n=>n!==id);compareDock();}if(el.dataset.nextFilter){if(el.dataset.nextFilter==='region')regionFilter=el.value;if(el.dataset.nextFilter==='student')studentFilter=el.value;if(el.dataset.nextFilter==='recruit')recruitFilter=el.value;refreshAtSamePosition();document.querySelector(`[data-next-filter="${el.dataset.nextFilter}"]`)?.focus({preventScroll:true});}if(el.dataset.futureField){future[el.dataset.futureField]=el.value;scenarioSnapshot=null;$('#scenarioResults').innerHTML='';}if(el.id==='changedOnly'){onlyChanged=el.checked;$('#scenarioResults').innerHTML=scenarioResults();}if(el.dataset.filePolicy){const d=extra.files.find(d=>d.id===el.dataset.filePolicy);if(d){d.policy=Number(el.value);saveExtra();refreshAtSamePosition();savedFeedback('문서를 준비할 정책에 연결했어요.');}}});
document.addEventListener('submit',e=>{const f=e.target;if(f.id==='nextGoalForm'){e.preventDefault();const v=new FormData(f).get('goal');if(!/^\d{4}-\d{2}-\d{2}$/.test(v))return;extra.goal=v;calendarOffset=0;saveExtra();refreshAtSamePosition();savedFeedback('나의 준비 목표일을 저장했어요.');}if(f.id==='nextSubmissionForm'){e.preventDefault();const fd=new FormData(f);extra.submitted=fd.get('confirmed')==='on';extra.receipt=String(fd.get('receipt')||'').trim().slice(0,100);saveExtra();$('#infoDialog').close();render();savedFeedback('본인이 확인한 제출 기록을 저장했어요.');}},true);
document.addEventListener('submit',e=>{const f=e.target;if(f.id!=='profileForm')return;f.querySelectorAll('.new-error').forEach(el=>el.remove());f.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));const age=Number(f.elements.age.value),res=f.elements.residence.value.trim();const invalid=!Number.isInteger(age)||age<15||age>100||!res;if(invalid){e.preventDefault();e.stopImmediatePropagation();const input=(!Number.isInteger(age)||age<15||age>100)?f.elements.age:f.elements.residence;const p=document.createElement('p');p.className='new-error';p.textContent=input===f.elements.age?'만 나이를 15~100 사이의 정수로 입력해 주세요.':'주민등록상 주소의 지역을 입력해 주세요.';input.setAttribute('aria-invalid','true');input.closest('div').append(p);input.focus();}},true);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.dataset.action!=='about')return;e.stopImmediatePropagation();openDialog('나의 다음을, 가볍게 픽.',`<p>청년픽 NEXT는 생활권에 맞는 정책을 살펴보고 조건 확인과 신청 준비를 이어가는 UI 프로토타입이에요.</p><div class="issuance-note"><strong>이번 화면에서 할 수 있어요</strong><p>정책 검색·필터·저장·비교 / 생활변화 가정 비교 / 준비 점검·목표일 / 문서 직접 보관·다운로드 / AI 내비게이터 시연 대화</p></div><p>정책 3개는 예시예요. 공식 공고, 외부 전자지갑, 실시간 생성형 AI는 아직 연결되지 않았어요. 직접 보관한 문서와 입력 내용은 이 기기의 브라우저에 저장해요.</p>`);},true);
document.addEventListener('keydown',e=>{const t=e.target.closest('[role="tab"][data-wallet-tab]');if(t&&['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();const keys=['documents','guides','files','activity'],i=keys.indexOf(walletUI.tab);walletUI.tab=keys[e.key==='Home'?0:e.key==='End'?3:(i+(e.key==='ArrowRight'?1:3))%4];walletUI.query='';walletUI.category='all';updateWalletWorkspace(`[data-wallet-tab="${walletUI.tab}"]`);}},true);
render();
})();
